create table if not exists public.seed_comments (
  id uuid primary key default gen_random_uuid(),
  donation_id uuid unique references public.donations(id) on delete cascade,
  legacy_key text unique,
  display_name text not null,
  body text not null,
  amount numeric(10, 2),
  seed_count integer,
  source text not null default 'payment' check (source in ('legacy', 'payment')),
  created_at timestamptz not null default now()
);

create index if not exists seed_comments_created_at_idx
on public.seed_comments (created_at desc);

create index if not exists seed_comments_donation_id_idx
on public.seed_comments (donation_id);

alter table public.seed_comments enable row level security;

drop policy if exists "Public can read seed comments" on public.seed_comments;
create policy "Public can read seed comments"
on public.seed_comments for select
using (true);

drop policy if exists "Admins can manage seed comments" on public.seed_comments;
create policy "Admins can manage seed comments"
on public.seed_comments for all
using (public.is_admin())
with check (public.is_admin());

on conflict (legacy_key) do nothing;
